package com.example.orderdesk.order;

import static org.assertj.core.api.Assertions.assertThat;

import jakarta.validation.Validation;
import jakarta.validation.Validator;
import java.math.BigDecimal;
import java.util.Collections;
import org.junit.jupiter.api.Test;

class CreateOrderRequestTest {
  private final Validator validator = Validation.buildDefaultValidatorFactory().getValidator();
  private final OrderLine line = new OrderLine("A-1", 1, new BigDecimal("1.00"));

  @Test
  void fiftyLinesAreAccepted() {
    var request = new CreateOrderRequest(3L, Collections.nCopies(50, line));
    assertThat(validator.validate(request)).isEmpty();
  }

  @Test
  void fiftyOneLinesAreRejected() {
    var request = new CreateOrderRequest(3L, Collections.nCopies(51, line));
    assertThat(validator.validate(request)).extracting(v -> v.getPropertyPath().toString()).containsExactly("lines");
  }
}
